// Genuine GA questions, keyed to the source paper. Explanations are newly written.
// The question artwork is displayed from a lossless SVG view of the original PDF page.
export const aptitudePyqs=[];
function set(year,session,file,keyPage,keySource,keys,rows){
  rows.forEach(([number,page,title,category,principle,steps,check],i)=>{
    const accepted=keys[i].split('').map(c=>c.charCodeAt(0)-65);
    aptitudePyqs.push({id:`apt-pyq-${year}-${session}-${number}`,topic:'apt',bank:'pyq',year,session,number,
      prompt:title,category,marks:(year===2017?number<=60:number<=5)?1:2,
      choices:['Option A in the source question','Option B in the source question','Option C in the source question','Option D in the source question'],
      key:accepted[0],acceptedKeys:accepted,file,page,keyPage,keySource,
      sourceImage:`./aptitude-pages/${year}-${session}-${number}.svg`,
      why:[`Principle: ${principle}`,...steps.map((s,j)=>`Step ${j+1}: ${s}`),`Answer: Option ${keys[i].split('').join(' or ')}.`,`Check and interpretation: ${check}`].join('\n\n')});
  });
}
set(2016,'GA1','EC2016.pdf',20,'./papers/EC2016.pdf#page=20',
 ['A','B','A','A','C','C','B','D','C','C'],[
 [1,1,'Superlative usage: Mount Everest','Verbal','A definite article normally introduces a superlative identifying a unique member of a set.', ['Identify the comparison as a superlative: highest, not merely high.','Use the definite article before highest and retain the geographical comparison with the world.','The grammatically complete noun phrase appears in option A.'],'The alternatives omit the article or use a singular noun after one of, which requires a plural noun.' ],
 [2,1,'Choosing the correct verb after did','Verbal','An auxiliary did is followed by the base form of a verb.', ['The sentence asks what was lost in a theft.','Lose is the verb meaning to cease to possess; loose is normally an adjective meaning not tight.','Option B supplies the correct base-form verb.'],'Loss is a noun and louse is unrelated to the intended meaning.' ],
 [3,1,'Medicine: meaning and collocation','Verbal','A coherent contrast must connect clinical effectiveness with prescribing behavior.', ['The first blank requires a noun describing how well the medicine treats the condition.','The second requires a past participle describing doctors recommending it.','Effectiveness and prescribed form the coherent pair in option A.'],'Proscribed means prohibited, which is the opposite of prescribed and changes the intended statement.' ],
 [4,1,'Weighted percentages of ripe and unripe fruit','Quantitative','Apply each conditional apple percentage to the size of its own fruit group.', ['Unripe apples comprise 0.15×0.45=0.0675 of all fruit.','Ripe apples comprise 0.85×(1−0.66)=0.289 of all fruit.','The apple fraction is 0.3565; multiplying by 5,692,000 gives 2,029,198.'],'The ripe-apple percentage is 34%, not the given ripe-orange percentage of 66%.' ],
 [5,1,'Distance satisfying an interval','Analytical','Translate comparative statements into strict numerical inequalities.', ['Ahmed is 5 km away and Susan is 7 km away.','Arun is farther than the former and closer than the latter, so 5<d<7.','Only 6.02 km, option C, lies inside this interval.'],'The statements do not require the people to lie on a straight line; only distances from the same reference point are compared.' ],
 [6,1,'Infection without symptoms','Quantitative','Use the product rule for the probability of an event and a specified conditional outcome.', ['The probability of becoming infected is 0.5.','Given infection, not developing the disease has probability 1−0.3=0.7.','The required joint fraction is 0.5×0.7=0.35=35%.'],'Subtracting 30 percentage points from 50% incorrectly treats a conditional percentage as a population percentage.' ],
 [7,2,'Passage inference about friendship','Verbal','Distinguish the person’s prior belief from what the later events demonstrate.', ['The passage explicitly says he was confident his friends would reciprocate his help.','It then states that the events of the previous week proved that expectation wrong.','Thus statements (iii) and (iv) are supported, giving option B.'],'There is no statement that his friends were always asking for help, nor that he originally expected betrayal.' ],
 [8,2,'Age ordering independent of chess ability','Analytical','Combine age comparisons without drawing conclusions about unrelated skills.', ['Leela is older than Pavithra.','Shiva is older than Leela, so the age order is Shiva>Leela>Pavithra.','Pavithra is therefore the youngest, option D.'],'A separate fact about chess wins cannot determine Shiva’s ability or reverse the age ordering.' ],
 [9,2,'Cyclic exponents','Quantitative','Convert reciprocal-power relations to logarithmic identities and multiply the resulting ratios.', ['The relations give a ln q=ln r, b ln r=ln s, and c ln s=ln q.','For the nondegenerate logarithmic interpretation of the question, a=ln r/ln q, b=ln s/ln r and c=ln q/ln s.','Their product telescopes to abc=1.'],'The cyclic cancellation is the intended aptitude method; exceptional bases such as one would need separate assumptions.' ],
 [10,2,'Comparing work with unequal hours and leave','Quantitative','Completed work is hourly rate times actual hours worked.', ['Q needs 25×12=300 hours for the job and works (7−2)×12=60 hours, completing 1/5.','R needs 50×12=600 hours and works 7×18=126 hours, completing 21/100.','Their contribution ratio is (20/100):(21/100)=20:21.'],'Both daily hours and the two days of leave must be included; comparing only nominal completion days is insufficient.' ]
]);
set(2016,'GA3','EC2016.pdf',39,'./papers/EC2016.pdf#page=39',
 ['C','B','C','C','B','D','A','D','C','B'],[
 [1,22,'Comparative adjective for height','Verbal','Use the conventional comparative adjective for a person’s height.', ['The two measurements are heights, not lengths of objects.','The adjective tall has comparative taller.','The sentence using taller than is option C.'],'Longer, lengthier and more elongated do not express the intended ordinary comparison of people’s heights.' ],
 [2,22,'Choosing the verb for honoring a teacher','Verbal','Vocabulary must fit the action and its object, not merely resemble another word in spelling.', ['The occasion is honoring the teacher for long service.','Felicitated means congratulated or honored.','It fits the sentence in option B.'],'Facilitated means made easier and does not mean offered congratulations.' ],
 [3,22,'Meaning of an idiom in context','Verbal','Interpret an idiomatic phrase by its conventional meaning within the narrative.', ['The sentence describes a turning point followed by a notable career.','The idiom indicates that the later developments are familiar to the audience.','Thus the remaining story is well known, option C.'],'The phrase is not a literal instruction about historical records or something being archaic.' ],
 [4,22,'Units and square-root equality','Quantitative','Equal square roots imply equal nonnegative quantities with compatible physical dimensions.', ['The given equality concerns the square roots of two lengths.','Squaring both sides gives 9 inches=0.25 yards.','This agrees with 1 yard=36 inches, since 0.25×36=9.'],'Do not take square roots only of the numbers while leaving the unit exponents unchanged.' ],
 [5,22,'Work contribution with efficiency and shifts','Quantitative','Contribution scales jointly with efficiency, working days and hours per day.', ['Let E’s efficiency be e and working days be d. E works 12d hours.','M has efficiency 2e, works d/2 days, and has 6-hour shifts, contributing 2e×(d/2)×6=6ed.','E contributes 12ed, so M:E=1:2.'],'The doubled efficiency cancels the halved days but not M’s shorter daily shift.' ],
 [6,23,'Union of reading and sports in a Venn diagram','Analytical','For a union, count every disjoint region belonging to either set exactly once.', ['Include the reading-only and sports-only regions: 13 and 15.','Also include the reading–TV, reading–sports, sports–TV and triple regions: 12,44,17,7.','Their sum is 13+15+12+44+17+7=108.'],'The TV-only region 19 is excluded; the overlapping regions must not be counted twice.' ],
 [7,23,'Inference about origins of disciplines','Verbal','Only conclusions entailed by the stated chronology are justified.', ['The passage states that the disciplines existed before they were institutionalized in the colonial period.','Therefore their origin preceded colonial institutionalization.','Only inference (ii) is established, giving option A.'],'An obsolete mode of knowledge production does not imply that the entire discipline has become obsolete.' ],
 [8,23,'Mirror-clock time followed by elapsed time','Quantitative','For a conventional clock mirror, actual and apparent readings sum to 12:00 modulo 12 hours.', ['The mirror reading 1:30 corresponds to actual time 10:30.','That was 2 hours 15 minutes before the current time.','Adding the interval gives 12:45, option D.'],'The elapsed time must be added to the corrected actual reading, not to the mirror image.' ],
 [9,23,'Resultant displacement in diagonal directions','Spatial','Resolve northeast and southeast travel into equal Cartesian components.', ['M ends at (10+10/√2,10/√2). N ends at (4/√2,−5−4/√2).','The component differences are 10+6/√2 and 5+14/√2.','Their Euclidean norm is approximately 20.61 km.'],'The diagonal distances are hypotenuses, so their individual components must be divided by √2.' ],
 [10,24,'Wire allocation minimizing total area','Quantitative','Express both areas in one variable using the fixed total perimeter, then minimize the quadratic.', ['Let square side be x and rectangle short side be y; the wire constraint is 4x+6y=340.','Total area is x²+2y²=x²+2[(340−4x)/6]².','Differentiation gives 2x−(4/9)(340−4x)=0, hence 34x=1360 and x=40 mm.'],'The second derivative is positive, and the resulting positive rectangle dimensions satisfy the wire constraint.' ]
]);
set(2016,'GA4','EC2016.pdf',63,'./papers/EC2016.pdf#page=63',
 ['C','C','B','CD','A','D','A','C','B','A'],[
 [1,41,'Comparing the prices of two objects','Verbal','A grammatical comparison should compare like quantities.', ['The subject is the price of an apple.','It must be compared with the price of an onion, rather than with an onion itself.','Option C uses that of to stand for the price of the onion.'],'The phrase more costlier is also ungrammatical because it doubles the comparative marker.' ],
 [2,41,'Vocabulary in the hot-coal analogy','Verbal','Find the closest ordinary synonym in the given physical metaphor.', ['The relevant action is gripping a coal in the hand.','Clutching means holding or grasping tightly.','Therefore option C preserves the action and meaning.'],'Burning describes an effect, igniting a start of combustion, and flinging a throwing action rather than holding.' ],
 [3,41,'Family relation without assuming gender','Analytical','Use parent–child relationships and avoid inventing information about a child’s gender.', ['M’s son is Q and E is M’s daughter-in-law, so E belongs to the next-generation couple in the intended family structure.','E is the mother of P.','P is therefore M’s grandchild, option B.'],'Nothing supplied determines whether P is a grandson or granddaughter, so the gender-neutral relation is required.' ],
 [4,41,'Odd-one-out among four integers','Analytical','An odd-one-out rule can be ambiguous when different properties distinguish different members.', ['The values 324,441 and 64 are perfect squares, while 97 is not; this selects C.','Another pattern can distinguish 64 as a perfect cube among the listed values.','The published key explicitly accepts C or D for this MCQ, so either selection is graded correct here.'],'These are alternative accepted answers, not a request to select both as an MSQ.' ],
 [5,41,'Train speeds from passing a post','Quantitative','A train passing a point travels its own full length.', ['The first speed is 120/10=12 m/s.','The second speed is 150/15=10 m/s.','The magnitude of their difference is |12−10|=2 m/s.'],'Relative direction does not matter because the question asks for the difference in speed magnitudes, not a crossing time.' ],
 [6,42,'Odometer increase from a signed velocity graph','Quantitative','An odometer measures distance, which is the integral of speed |v| rather than signed velocity.', ['From 0 to 4 s, the positive areas are 0.5+1+1.5+1=4 m.','The negative-velocity triangle from 5 to 7 s contributes magnitude 1 m of additional travel.','Total odometer increase is 4+1=5 m.'],'Signed area would give displacement of 3 m, but reversing direction does not reduce an odometer reading.' ],
 [7,42,'Scope of a public-health passage inference','Verbal','Separate the stated concern from stronger causal or global claims.', ['The passage explicitly describes the number of infected people in India as overwhelming.','It predicts reduction through vaccination, not guaranteed elimination.','Only the conclusion that India has a high number of infections is supported, option A.'],'No comparison with other countries or proof of global causation is provided.' ],
 [8,42,'Finding the oldest roommate','Analytical','Represent all ages relative to one common reference.', ['Let Sravan’s age be s. Manu is s+2 months and Pavan is s+1.','Sravan is three months younger than Trideep, so Trideep is s+3.','Trideep is oldest and receives the extra space, option C.'],'The comparisons are relative, so the actual birth dates are unnecessary.' ],
 [9,42,'Area bounded by two lines and the first-quadrant axes','Quantitative','Find the polygon’s vertices from axis intercepts and the intersection, then apply an area formula.', ['Solving 3x+2y=14 and 2x−3y=5 gives intersection (4,1).','The first-quadrant bounded polygon has vertices (0,0),(2.5,0),(4,1),(0,7).','The shoelace area is (2.5×1+4×7)/2=15.25 square units.'],'The axes are part of the bounded region; using only a triangle from one line ignores the second boundary.' ],
 [10,43,'Line fitted against a logarithmic coordinate','Quantitative','A straight line in (ln x,y) uses ln x as its horizontal variable.', ['The zero crossing occurs at ln x=0.1, so y=−0.02(ln x−0.1).','For x=5, ln 5≈1.60944.','Thus y≈−0.02×1.50944=−0.03019, closest to −0.030.'],'Using x directly instead of ln x changes the fitted coordinate system and produces a wrong prediction.' ]
]);
set(2017,'EC2','EC2-2017.pdf',32,'./papers/EC2-2017.pdf#page=32',
 ['C','A','B','A','D','A','D','C','C','B'],[
 [56,28,'Adverb matching two ordered lists','Verbal','Use the adverb that maps items in one list to items in another in the same order.', ['Two dates are paired with two weekdays.','The intended mapping is first date to first weekday and second date to second weekday.','Respectively expresses exactly this correspondence, option C.'],'Retrospectively concerns looking backward in time rather than matching list positions.' ],
 [57,28,'Comparative adjective and comparison marker','Verbal','A comparison between two items normally uses a comparative adjective followed by than.', ['The sentence compares the ease of reading this year’s book with last year’s.','The comparative form of easy is easier.','The correct pair is easier and than, option A.'],'Most easy and easiest are superlatives, and from is not the standard comparison marker here.' ],
 [58,28,'Testing a one-way age rule','Analytical','To test P⇒Q, inspect cases with P true and cases with Q false; the others cannot falsify the rule.', ['The rule is drinking beer implies being over 18.','Check P’s drink because P is underage, and check S’s age because S is drinking beer.','Q is already old enough, while R is not drinking beer, so neither can violate the implication.'],'The necessary checks are P’s drink and S’s age, option B; the rule does not require every adult to drink beer.' ],
 [59,28,'Tracking a journey after turning toward the origin','Spatial','Use coordinates and a unit vector to apply a specified distance in a diagonal direction.', ['After moving north 3 and east 4, the person is at (4,3), which is 5 km from the origin.','Travelling 15 km toward the origin gives (4,3)−3(4,3)=(−8,−6).','Moving north another 6 km gives (−8,0), so the origin is 8 km east.'],'The 15 km move continues past the origin; stopping at the origin would incorrectly use only 5 km of the move.' ],
 [60,29,'Three-set inclusion–exclusion','Quantitative','The union of three sets equals individual totals minus pair intersections plus the triple intersection.', ['All 500 students belong to at least one course, so the union is 500.','Individual totals sum to 329+186+295=810; pair totals sum to 83+217+63=363.','Thus 500=810−363+x, giving x=53.'],'The pair totals include the triple-enrolled students; the final +x restores the amount subtracted too many times.' ],
 [61,29,'Authorial perspective in a passage','Verbal','Identify the author’s stated limitation rather than reversing it into a strength.', ['The author says proximity to the actors prevented the necessary perspective.','This explicitly limits the impartiality of the account.','Option A restates that intimate association need not permit the required perspective.'],'The alternatives assert impartiality or add unsupported generalizations, opposite to the passage’s qualification.' ],
 [62,29,'Family-tree contradiction','Analytical','Combine the stated marriage and generation relations while retaining the rule that each person has married at most once.', ['X and Y form one couple and have children P and Q.','Z and W form another couple and are parents of R; Z is also grandfather of S, P’s daughter.','These links place R in the parental couple connected to P and S in the intended tree, making the assertion that P and R are not married necessarily false.'],'Option D is the keyed contradiction; do not assume the genders of X or P merely from their labels.' ],
 [63,29,'Solving productivity of two worker groups','Quantitative','Express one job using worker rates in a common weekly time unit, then eliminate one rate.', ['Let a man and a woman complete m and w jobs per week. Then 1200m+500w=1/2.','The second team gives 900m+250w=1/3. Doubling it and subtracting the first gives 600m=1/6.','Thus m=1/3600, and 3600 men complete one job in one week.'],'Worker counts must be multiplied by the same time unit before comparing the two teams.' ],
 [64,30,'Counting three-digit numbers avoiding a substring','Quantitative','Count the complement by enumerating positions of the forbidden adjacent digit pair.', ['There are 900 three-digit numbers from 100 through 999.','The substring 21 can occupy hundreds–tens in 10 numbers or tens–units in 9 numbers.','Those cases do not overlap for a three-digit number, so the allowed count is 900−10−9=881.'],'The leading digit cannot be zero in the tens–units case, which is why that position contributes nine rather than ten.' ],
 [65,30,'Steepest path on a contour plot','Spatial','Slope magnitude is elevation change divided by horizontal distance; closely spaced contours indicate a steeper path.', ['Contour intervals in the plot are equal at 25 m.','Compare how rapidly the paths from P cross those contour levels over distance.','The P-to-R direction crosses the most tightly spaced contours, giving option B.'],'A higher endpoint alone does not prove a steeper path; the horizontal distance and contour spacing matter.' ]
]);
set(2018,'GA5','EC2018.pdf',21,'./papers/EC2018.pdf#page=21',
 ['B','A','B','D','B','B','B','C','C','D'],[
 [1,1,'Homophones in a sentence','Verbal','Words pronounced alike can have different grammatical roles and meanings.', ['A portion of cake is a piece.','An absence of conflict in the home is peace.','The ordered pair piece, peace is option B.'],'Peas is a food plural but does not name a portion of cake; reversing the two words breaks both meanings.' ],
 [2,1,'Contrast and contextual vocabulary','Verbal','A sentence beginning even though sets up a contrast between potential and actual attention.', ['A broad scope for improvement expresses unrealized potential.','Calling the sector neglected describes its lack of attention.','These words form the coherent contrast in option A.'],'The alternatives create unrelated or contradictory word combinations rather than the intended contrast.' ],
 [3,1,'Digit divisibility by three','Quantitative','An integer is divisible by three exactly when its digit sum is divisible by three.', ['The known digits sum to 7+1+5+4+2+3=22.','The missing digit d must satisfy 22+d≡0 mod 3, so d≡2 mod 3.','The smallest allowed digit is 2, option B.'],'Leading-position constraints do not apply because the unknown digit is internal to the number.' ],
 [4,1,'Infinite geometric series','Quantitative','For |r|<1, an infinite geometric series with first term a has sum a/(1−r).', ['The first term is 1 and the common ratio is 1/4.','Since the ratio magnitude is below one, the series converges.','Its sum is 1/(1−1/4)=4/3, option D.'],'Adding only a few initial terms gives an approximation rather than the exact infinite sum.' ],
 [5,1,'Similar triangles with a lamp and shadow','Spatial','The lamp and shadow geometry forms similar right triangles.', ['The person is 1.5 m tall and the shadow is twice that, hence 3 m.','The lamp-to-shadow-tip distance is 3+3=6 m.','Similarity gives H/6=1.5/3, so the lamp height is 3 m.'],'The large triangle includes both the distance to the person and the shadow length.' ],
 [6,1,'Present value under annual compounding','Quantitative','The present deposit equals the future amount divided by the compound-growth factor.', ['After five years, deposit P grows to P(1.1)⁵.','Set that equal to 1,000,000 and solve P=1,000,000/1.61051≈620,921.32.','The listed rounded deposit 621,000 is the appropriate option B.'],'Using simple interest would understate the five-year growth factor and miscalculate the required principal.' ],
 [7,2,'Equal-mass mixture of two alloys','Quantitative','Convert each alloy ratio to a fraction of its total mass before averaging equal masses.', ['Alloy A has gold fraction 2/5 and copper fraction 3/5.','Alloy B has gold fraction 3/10 and copper fraction 7/10.','Equal masses produce gold:copper=(4/10+3/10):(6/10+7/10)=7:13.'],'Adding the raw ratio numerators and denominators would ignore that the original ratios use different total part counts.' ],
 [8,2,'Inference about leadership development','Verbal','A passage inference must follow from the account, rather than merely being plausible.', ['The long search for a complete captain supports inference (ii).','The replacement of the earlier low-scoring picture by a successful batsman-captain supports (iv).','Only (ii) and (iv) form the keyed combination, option C.'],'Potential as a junior is not the same as already being a good captain, and differing fan and board preferences are not established.' ],
 [9,2,'Witness reliability with unequal base rates','Quantitative','Bayes’ theorem combines witness accuracy with the prior prevalence of each cab color.', ['True-blue reports occur with probability 0.15×0.8=0.12.','False-blue reports from green cabs occur with probability 0.85×0.2=0.17.','The posterior is 0.12/(0.12+0.17)≈0.4138, closest to 41%.'],'The witness’s 80% accuracy alone is not the posterior probability because green cabs are much more common.' ],
 [10,3,'Inference from improved tourist access','Verbal','Choose a consequence directly supported by the proposed change, not an unproved environmental prediction.', ['The passage identifies inaccessibility as a current obstacle to tourism.','The proposed helicopter service removes a connectivity barrier while a resort supplies accommodation.','Increased tourist access and arrivals is the supported inference, option D.'],'Crowding, pollution and cultural change are concerns or possibilities, not established outcomes in the stated evidence.' ]
]);
set(2020,'EC','EC2020.pdf',19,'./papers/EC2020.pdf#page=19',
 ['A','B','B','C','A','A','B','C','C','B'],[
 [1,1,'Prepositions for accidents and disease','Verbal','Use standard verb–preposition combinations for the specified causes.', ['English describes people as killed in accidents.','For the second clause the conventional phrase is die of a disease.','The pair in, of is option A.'],'The two blanks attach to different verbs, so the same preposition need not fit both.' ],
 [2,1,'Correlative conjunction','Verbal','Not only is conventionally paired with but also when adding another parallel assertion.', ['The first part introduces theft through not only.','The second must add conspiracy in a parallel form.','But also completes the pair, giving option B.'],'Rather than would set up a contrast or substitution instead of adding a second accusation.' ],
 [3,1,'Word analogy using opposites','Verbal','Identify the semantic relation in the first pair before applying it to the second.', ['Explicit contrasts with implicit: expressed openly versus left unstated.','For express as a verb, the corresponding contrast is repress, to hold back expression.','Option B preserves the intended oppositional relation.'],'Similar word endings are not enough; the relation must match the first pair’s meaning.' ],
 [4,1,'Reading comprehension about unequal announcements','Verbal','Use the specific disparity described rather than a broad conclusion about language preference.', ['The passage states that English announcements lasted 15 seconds while French ones lasted 5 seconds.','The relevant complaint concerns this unequal duration.','Option C identifies the English announcements as longer.'],'The text does not say that French announcements were absent or less clear, only shorter.' ],
 [5,1,'Testing a superadditive function','Quantitative','Superadditivity requires f(x+y)≥f(x)+f(y) over the stated domain.', ['For f(x)=eˣ and x,y>1, let a=eˣ and b=eʸ, so both exceed e.','Then ab−a−b=(a−1)(b−1)−1>0.','Therefore e^(x+y)>eˣ+eʸ, establishing option A.'],'Square roots and reciprocal or decaying exponential alternatives do not satisfy the same inequality throughout this domain.' ],
 [6,2,'Chronological order of a passage','Verbal','Follow the causal and temporal chain explicitly described in the text.', ['The passage connects excess liquidity after the East Asian crisis with subprime lending.','Subprime lending leads into the banking crisis associated with the 2008 collapse.','That banking crisis develops into the global financial crisis, giving option A.'],'This ordering is a reading-comprehension result from the passage rather than an independent economic-history claim.' ],
 [7,2,'Clock angle at quarter past three','Quantitative','The hour hand moves continuously rather than remaining exactly on the hour marker.', ['At 3:15 the minute hand is at 90 degrees from twelve.','The hour hand is at 3×30+15×0.5=97.5 degrees.','Their smaller angle is 97.5−90=7.5 degrees.'],'Treating the hour hand as fixed at three would incorrectly give zero degrees.' ],
 [8,2,'Largest inscribed rectangle and remaining circle area','Spatial','A maximum-area rectangle with fixed diagonal is a square. Its diagonal equals the circle diameter.', ['Let rectangle sides be x and y, with x²+y²=(2a)²=4a².','Since 2xy≤x²+y², maximum rectangle area is xy=2a² at x=y.','Subtract it from circle area πa² to get (π−2)a², option C.'],'Using a² as the square area would confuse its side with the circle radius.' ],
 [9,2,'Repeated-root quadratic relation','Quantitative','Equal roots force the discriminant to zero and the repeated root to half the sum of roots.', ['The discriminant condition is b²=4ac for ax²−bx+c=0.','The repeated root is β=b/(2a), hence β³=b³/(8a³).','Substitute b²=4ac to obtain β³=bc/(2a²), option C.'],'The sign of the linear coefficient is already negative, so the root sum is +b/a.' ],
 [10,3,'Ratio of averages from a school-enrolment chart','Quantitative','When both averages use the same number of years, their common denominator cancels in the ratio.', ['Read school P values as 3,5,5,6,4 thousand, totaling 23.','School Q totals 4+7+8+7+5=31 thousand; the difference total is 31−23=8.','The average-P to average-difference ratio is (23/5):(8/5)=23:8.'],'Take the differences in enrolment, not the ratio of the two schools’ total enrolments.' ]
]);
set(2022,'EC','EC2022.pdf',1,'https://gate2026.iitg.ac.in/doc/download/Answer_keys2022/ec_2022.pdf',
 ['C','D','B','B','C','D','C','C','B','B'],[
 [1,1,'Correlative alternatives in a sentence','Verbal','Neither pairs with nor to negate both alternatives.', ['The sentence coordinates two language objects with the same verb.','Neither Japanese nor Chinese is a grammatically parallel negative pair.','Option C supplies neither and nor.'],'Either would pair with or, not nor; mixing the two correlation patterns is incorrect.' ],
 [2,1,'Shares from a ratio difference','Quantitative','A difference between shares determines the value of one ratio unit.', ['R and S have 4 and 3 parts respectively, a difference of one part.','That difference is ₹1000, so each part is ₹1000.','Q has two parts and receives ₹2000.'],'The total fund is not needed once one part has been fixed from the given difference.' ],
 [3,2,'Height of a trapezium from all four sides','Spatial','The difference between the parallel bases is split into horizontal projections of the two legs.', ['Let one projection be x; the other is 5−x because the bases differ by 11−6=5.','The equal-height equations are h²+x²=3² and h²+(5−x)²=4². Subtract to get 25−10x=7, hence x=1.8.','Then h=√(9−1.8²)=2.4 cm.'],'The shortest distance between parallel bases is the perpendicular height, not either slanted leg.' ],
 [4,3,'Counting squares while excluding a hole','Spatial','Count axis-aligned squares by size and subtract those containing the missing cell.', ['A full 4×4 grid has 16+9+4+1=30 squares.','The missing interior unit cell belongs to 1 square of size 1, 4 of size 2, 4 of size 3 and 1 of size 4.','Subtract 1+4+4+1=10 to get 20 intact squares.'],'The building-block condition refers to squares made from the grid’s unit cells; rotated shapes are not additional candidates.' ],
 [5,4,'Visibility in a nonconvex gallery','Spatial','A stationary guard sees a point only if the entire line segment to it stays inside the gallery.', ['The inward notch blocks views across the two upper arms from positions P and R.','From Q and S, straight sight lines can reach both arms and the lower region without crossing an opaque wall.','Thus the complete valid set is Q and S, option C.'],'A 360-degree viewing angle does not allow seeing through the boundary or around an inward corner.' ],
 [6,5,'Distinguishing possibility from certainty','Verbal','A valid inference must preserve the passage’s uncertainty rather than turn a possibility into a fact.', ['The passage says chemical control may have undesired consequences.','It says the consequences of the genetic approach remain to be seen.','Option D accurately combines the known concern with the unresolved question.'],'Neither a guarantee of safety nor a claim of definite genetic harm follows from the text.' ],
 [7,6,'Intersection of two strict inequalities','Quantitative','Solve each inequality separately, then intersect the permitted intervals.', ['2x−1>7 gives 2x>8, hence x>4.','2x−9<1 gives 2x<10, hence x<5.','Both hold exactly for 4<x<5, option C.'],'The endpoints are excluded because the original inequalities are strict.' ],
 [8,6,'Area from perpendicular diagonals','Spatial','The points form a rhombus whose diagonals are perpendicular, so its area is half the product of diagonal lengths.', ['The vertical diagonal joins (0,1) and (0,−3), giving length 4.','The horizontal diagonal joins (−2,−1) and (2,−1), also length 4.','Area is (1/2)×4×4=8 square units.'],'The coordinates must first be ordered around the boundary if using the shoelace formula; connecting them in arbitrary listed order can self-intersect.' ],
 [9,7,'Exactly one truthful statement','Analytical','Use the known truthful person’s statement to constrain the total number of true statements.', ['S is truthful and says exactly one person tells the truth, so every other statement must be false.','R’s statement that P did not copy is therefore false.','Hence P copied; P, Q and T then also make false claims consistently, giving option B.'],'Check the full truth pattern rather than identifying a suspect from only one accusation.' ],
 [10,8,'Composing square rotations','Spatial','Two half-turns about the two in-plane diagonals act on the square like a 180-degree planar rotation.', ['XY is equivalent on the labeled corners to Z², so it is not the identity.','XYZZ therefore corresponds to Z²Z²=Z⁴, the identity.','Sequence (3) is also Z⁴, so only sequences (1) and (3) are equivalent, option B.'],'Rotations about in-plane diagonal axes must not be confused with two ordinary 180-degree planar rotations.' ]
]);
set(2023,'EC','EC2023.pdf',1,'https://gate2026.iitg.ac.in/doc/download/Answer_keys2023/EC_ANS_GATE2023.pdf',
 ['C','A','C','C','C','D','A','B','A','C'],[
 [1,1,'Choosing a noun for moral judgment','Verbal','A possessive determiner followed by a subject noun requires the appropriate noun in meaning and grammar.', ['The sentence refers to an internal moral objection to supporting a proposal.','Conscience is the noun for that moral faculty.','Option C fits both meaning and syntax.'],'Conscious is an adjective; consensus is group agreement, and consent is permission rather than the intended moral faculty.' ],
 [2,1,'Institution and branch-of-government analogy','Verbal','Identify the functional branch associated with each institution.', ['Parliament belongs to the legislature.','Courts belong to the judiciary.','Judiciary, option A, therefore completes the parallel.'],'Executive is a different governmental branch and does not describe the courts’ role in this analogy.' ],
 [3,2,'Smallest distinct-digit number with a prescribed sum','Quantitative','To minimize a number, first minimize its number of digits and then order those digits increasingly without a leading zero.', ['The largest sum of eight distinct decimal digits is 9+8+7+6+5+4+3+2=44, so at least nine digits are needed.','The nine distinct nonzero digits sum to 45 exactly.','Their smallest ordering is 123456789, option C.'],'Repeated 9s can reach the sum with fewer digits but violate the distinct-digit requirement.' ],
 [4,2,'Two-set inclusion–exclusion with a ratio','Quantitative','Use the neither count to obtain the union before applying inclusion–exclusion.', ['The union contains 100−30=70 students. Let comedy count be c and romantic count be 2c.','Then 2c+c−20=70, so c=30.','The romantic count is 2c=60, option C.'],'The overlap must be subtracted once because it appears in both individual totals.' ],
 [5,3,'Rectangles in an intersecting-line figure','Spatial','Count rectangles by orientation, including tilted rectangles and the enclosing axis-aligned square.', ['The diagonal network contains three usable parallel lines in each of two perpendicular sloping directions.','Choosing two from each family gives C(3,2)²=9 tilted rectangles.','The enclosing square is one additional rectangle, for a total of 10.'],'Do not omit squares from the rectangle count, and do not count individual triangular regions as rectangles.' ],
 [6,4,'Set implications involving creatures','Analytical','Translate universal statements into subset relationships without reversing them.', ['Animals are a subset of ferocious creatures; clawed creatures are also a subset of ferocious creatures.','The passage states that clawed creatures exist.','Therefore some ferocious creatures have claws, option D.'],'Being ferocious does not by itself imply being an animal, so the converse relation is unsupported.' ],
 [7,5,'Matching a symmetric decaying graph','Quantitative','Use sign, symmetry and limiting behavior to eliminate formulas before detailed differentiation.', ['The graph is nonnegative on both sides, symmetric about zero and zero at zero.','A factor x² supplies these sign and origin properties, while 2^(−|x|) decays in both tails.','Thus option A matches; its two symmetric peaks are consistent with polynomial growth competing with exponential decay.'],'A factor x alone changes sign across zero, and 2⁻ˣ alone grows without bound in the negative tail.' ],
 [8,6,'Tense and viewpoint in a memory passage','Verbal','Past-tense recollection indicates the narrator’s current perspective on a former experience.', ['The narrator introduces the experience as something that happened during childhood.','The verbs describe earlier preferences and imagining, not a current child’s report.','Option B identifies an adult’s memory of childhood preferences.'],'The passage does not limit the reading to fragments or prescribe what all children should read.' ],
 [9,7,'Worst-case pooled-testing count','Quantitative','Maximize the number of positive groups when bounding the total tests.', ['There are 1000/5=200 pooled tests.','At most 100 groups can be positive because there are only 100 positive individuals; this bound is achieved by placing one in each positive group.','Retesting all five members of those groups uses 500 more tests, totaling 700.'],'Grouping positives together would reduce the number of positive pools, so it is not the worst case.' ],
 [10,8,'Creases after repeated halving','Spatial','Every complete halving doubles the number of stacked strips; internal boundaries are one fewer than the final number of strips.', ['Five folds turn the 32 cm width into 32/2⁵=1 cm.','When unfolded, the width is partitioned into 2⁵=32 strips.','There are 32−1=31 internal crease lines, option C.'],'The number of visible creases is not the number of folding operations because each later fold acts through multiple layers.' ]
]);
set(2024,'EC','EC2024.pdf',1,'https://gate2026.iitg.ac.in/doc/download/2024/ECFinalAnswerKey.pdf',
 ['A','A','B','C','A','C','D','C','A','A'],[
 [1,1,'Intensity ordering of vocabulary','Verbal','The analogy requires words in the same semantic field with increasing intensity.', ['The first chain progresses from attraction toward stronger fascination.','The second must progress through increasing weariness or boredom.','Jaded fits between bored and weary in the given analogy, option A.'],'Baffled concerns confusion and worsted concerns defeat, so neither follows the same semantic progression.' ],
 [2,2,'Inferring siblings from allowed room assignments','Analytical','Eliminate pairs ruled out either by family facts or by sharing a room in any acceptable arrangement.', ['S and Q are stated to have no siblings, so neither can be in the pair.','This leaves the relevant possibilities among P, R and T.','The acceptable allocations place the other possible pairs together at least once, leaving P and T as the sibling pair.'],'Both room diagrams must be checked; a pair being separated in only one diagram is not sufficient.' ],
 [3,3,'Age ratios at two different times','Quantitative','Use one pair of present ages to write both time-shifted ratio equations.', ['Let present ages be a and f. Five years ago gives f−5=4(a−5), or f=4a−15.','Five years later gives 5(a+5)=2(f+5), or 2f=5a+15.','Solving yields a=15 and f=45; their constant age difference is 30 years.'],'The father’s age when Aman was born equals the current age difference, not the father’s current age.' ],
 [4,3,'Reciprocal logarithms with different bases','Quantitative','The identity 1/log_b x=log_x b converts every term to a common base.', ['Rewrite the sum as log_x2+log_x3+log_x4.','Combine it to log_x(2×3×4)=log_x24.','Setting this equal to 1 gives x=24, option C.'],'The condition x>1 ensures the logarithms are defined with a valid base and removes exceptional base-one behavior.' ],
 [5,4,'Prime factor of a difference of powers','Quantitative','Factor out the lower power, then factor the small remaining difference.', ['3¹⁹⁹−3¹⁹⁶=3¹⁹⁶(3³−1).','Since 3³−1=26=2×13, the prime factors are 2,3 and 13.','The greatest is 13, option A.'],'A large exponent does not mean the largest prime factor must be large; factoring reveals the small residual factor.' ],
 [6,5,'Ordering a short narrative','Verbal','A coherent narrative introduces the principle, then the event, the student’s objection and finally the teacher’s reply.', ['R establishes the claim that life is an illusion.','S introduces the charging bull and the teacher’s escape; P then asks why he runs.','Q answers that question, giving the order RSPQ, option C.'],'Pronouns and the question–answer dependency prevent the reply from appearing before the objection.' ],
 [7,6,'Tape around four cylindrical chalk sticks','Spatial','The tight outer boundary consists of straight tangent segments and rounded arcs around the outside cylinders.', ['The four centers form a square of side 2r=1 cm, contributing straight boundary length 4 cm.','The four quarter-circle arcs together equal a full circle of radius 0.5 cm, contributing π cm.','Tape area is length×width=(4+π)×10=10(4+π) cm².'],'Wrapping each stick separately would count internal contact surfaces that are not on the outside of the bundle.' ],
 [8,7,'Testing ratios from a bar chart','Quantitative','Compare ratios using the values from each year rather than comparing only individual bars.', ['The chart gives normal shares 50% then 30%, and obese shares 15% then 25%.','Obese/normal rises from 15/50=0.3 to 25/30≈0.8333.','Thus the claim that this ratio decreased is incorrect, option C.'],'The other options agree with overweight/normal increasing, underweight/normal decreasing, and the normal share itself decreasing.' ],
 [9,8,'Successive mirror and water reflections','Spatial','A horizontal reversal followed by a vertical reversal is equivalent to a 180-degree planar rotation.', ['A mirror reverses left and right in the drawing; a water reflection reverses top and bottom.','To recover the original, undo both operations, equivalently rotate the given image by 180 degrees.','Both character order and each character’s orientation then match option A.'],'Reversing the character order alone is insufficient because individual symbol orientations also change.' ],
 [10,9,'Perimeters after direction-dependent folds','Spatial','A fold axis leaves the parallel dimension unchanged and halves the perpendicular dimension.', ['Two folds parallel to the initial long edge give sheet A dimensions 24×4 cm, with perimeter 56 cm.','Two folds parallel to the initial short edge give sheet B dimensions 6×16 cm, with perimeter 44 cm.','The ratio is 56:44=14:11, option A.'],'The axes are referenced to the initial edges, as specified; reclassifying the long edge after each fold would change the operation.' ]
]);
set(2025,'EC','EC2025.pdf',1,'https://gate2026.iitg.ac.in/doc/download/2025_Key/EC_Keys.pdf',
 ['A','D','B','B','A','B','D','C','B'],[
 [1,1,'Decreasing intensity in analogous word groups','Verbal','Match both the direction of intensity and the positive or negative meaning of the group.', ['The first group moves from a stronger negative action toward a milder one.','The second therefore needs a word stronger than praise, followed by appreciate.','Extol means praise highly and supplies the required stronger term, option A.'],'A word merely associated with approval is insufficient if it does not preserve the stated intensity ordering.' ],
 [2,1,'Unreal past conditional','Verbal','An inverted past-perfect condition normally pairs with could have or would have plus a past participle.', ['Had I learnt expresses an unreal earlier condition.','The imagined result is also in the unreal past, not the present or future.','Could have been fits that temporal and conditional structure, option D.'],'Will be and am going to be describe future outcomes and do not match the stated unreal past condition.' ],
 [3,2,'Frequency ratio across musical semitones','Quantitative','Multiply the equal per-note frequency ratio once for each semitone step.', ['From C to F-sharp there are six semitone intervals.','Each interval multiplies frequency by 2^(1/12).','The total ratio is [2^(1/12)]⁶=2^(1/2)=√2, option B.'],'The given starting frequency cancels in the ratio and is not needed for the calculation.' ],
 [4,3,'Length growth of an iterative curve','Spatial','Total curve length is the number of segments multiplied by segment length.', ['Each existing segment is replaced by five segments, each one-third as long.','One iteration therefore multiplies total length by 5/3.','Starting from length one, after n iterations the length is (5/3)ⁿ, option B.'],'The segment count and segment length change together; tracking only one of them misses the growth factor.' ],
 [5,4,'Graph of a sign-dependent expression','Quantitative','Resolve the absolute value separately on positive and negative inputs.', ['For x>0, |x|=x and −|x|/x=−1.','For x<0, |x|=−x and −|x|/x=+1.','The graph with left level +1 and right level −1 is option A; zero is excluded.'],'This is a two-level function, not a reciprocal curve; cancellation must account for the sign of x.' ],
 [6,5,'Coherent paragraph about adaptation','Verbal','Arrange a general introduction before the conditions, mechanism and long-term consequence.', ['Q introduces organisms adapting to their environment.','S explains why environmental change favors adaptable organisms; R identifies natural selection as the mechanism.','P gives the long-term evolutionary result, so the sequence is QSRP, option B.'],'The words this process and over time require an earlier account of the process they refer to.' ],
 [7,6,'Triangle inequalities for three broken-stick pieces','Quantitative','With total perimeter one, a nondegenerate triangle requires every piece to be shorter than one-half.', ['The three lengths are b₁, b₂−b₁ and 1−b₂.','Their half-perimeter conditions are b₁<0.5, b₂<b₁+0.5 and b₂>0.5.','These are A,B and C. The extra inequality b₁+b₂<1 is not necessary, so choose D.'],'For example b₁=0.4 and b₂=0.7 form lengths 0.4,0.3,0.3, yet b₁+b₂=1.1.' ],
 [9,8,'Checking total-medal statements','Quantitative','Compute all totals before comparing rankings and combined shares.', ['Totals are USA 125, Canada 90, Japan 45, Australia 52 and France 64.','The five-country total is 376, while USA+Canada=215.','Since 215>376/2=188, the claim that their share is below 50% is false, option C.'],'France is third by total and Canada’s 90 is exactly twice Japan’s 45, so those alternatives remain true.' ],
 [10,9,'Piecewise overhead plus tax under a price cap','Quantitative','For the relevant upper fee slab, form the pre-tax bill, then apply tax to the entire subtotal.', ['Let fee be f>500,000. Overhead is 100,000+0.1(f−500,000)=0.1f+50,000.','The final bill is 1.18(1.1f+50,000), which cannot exceed 1,000,000.','Solving gives f≤[1,000,000/1.18−50,000]/1.1≈724,961.48, so the listed maximum is option B.'],'The solution lies above 500,000, validating the slab used. Tax is applied to fee plus overhead, not to the fee alone.' ]
]);
