aptitudePyqs.push({id:'apt-pyq-2026-EC-1',topic:'apt',bank:'pyq',year:2026,session:'EC',number:1,marks:1,category:'Verbal',
 prompt:'Which word is opposite in meaning to nocturnal?',choices:['Normal','Diurnal','Abnormal','Exceptional'],key:1,acceptedKeys:[1],
 file:'https://gate2026.iitg.ac.in/doc/download/2026/QPs/EC.pdf',page:1,
 keySource:'https://gate2026.iitg.ac.in/doc/download/2026/Keys/EC_Keys.pdf',keyPage:1,
 why:'Principle: An antonym reverses the relevant meaning of a word.\n\nStep 1: Nocturnal describes activity at night.\n\nStep 2: The contrasting time of activity is daytime.\n\nStep 3: Diurnal is the standard word for daytime activity, so choose B.\n\nAnswer: Option B.\n\nCheck and interpretation: Normal, abnormal and exceptional describe other qualities rather than the night-versus-day distinction.'});
